fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    // Pre‐allocate exactly the capacity we need
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    // Extend with all elements of v1
    result.extend_from_slice(&v1[..]);
    // Then extend with all elements of v2
    result.extend_from_slice(&v2[..]);
    result
}

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // We assume `first` is non‐empty by problem statement
    let n1 = first.len();
    // Allocate space for (first.len() - 1) + second.len()
    let mut result = Vec::with_capacity((n1 - 1) + second.len());
    // Copy all of `first` except its last element
    result.extend_from_slice(&first[..n1 - 1]);
    // Then append all of `second`
    result.extend_from_slice(&second[..]);
    result
}

